      ],
      "impact": "The IMU will be in SPI mode and will not respond to I2C; the navigation computer cannot read the IMU.",
      "confidence": 0.95
    },
    {
      "category": "bridged_nets",
      "components": ["U10", "NAVC1"],
      "pins": ["U10.2", "NAVC1.42"],
      "nets": ["UART1_TX_NAVC"],
      "observed": "GPS U10 TXD (pin 2) is connected to UART1_TX_NAVC, which is the NAVC MCU's transmit pin (PA9). GPS RXD (pin 3) is connected to UART1_RX_NAVC (PA10).",
      "expected": "UART TX and RX must cross: GPS TXD should connect to NAVC UART1_RX_NAVC, and GPS RXD to NAVC UART1_TX_NAVC.",
      "evidence": [
        {"source": "schematic", "quote": "U10 MAX-8Q pin 2 TXD -> UART1_TX_NAVC; pin 3 RXD -> UART1_RX_NAVC (NAVC Peripherals sheet)"},
        {"source": "spec", "quote": "GPS receiver | NAVCPeripherals | u-blox MAX-8Q"}
      ],
      "impact": "GPS and NAVC UART transmitters drive the same net; communication fails and may cause contention.",
      "confidence": 0.95
    },
    {
      "category": "wrong_value",
      "components": ["R5"],
      "pins": ["R5.1", "R5.2"],
      "nets": ["+5V", "REG_FB"],
      "observed": "R5 is 8k8 and R6 is 1k3, giving Vout = 0.8*(1+8.8/1.3) ≈ 6.2 V.",
      "expected": "For a 5 V output with R6=1k3, R5 should be 6k8 (Vout ≈ 5.0 V).",
      "evidence": [
        {"source": "schematic", "quote": "R5 8k8; R6 1k3; note Vout=0.8*(1+R5/R6) (Power sheet)"},
        {"source": "spec", "quote": "5 V rail: A MIC26903YJL-TR synchronous buck regulator steps the battery input down to 5 V."}
      ],
      "impact": "The 5 V rail will be about 6.2 V, overvolting 5 V loads and possibly damaging them.",
      "confidence": 0.85
    }
  ],
  "summary": "The schematic contains three deviations: the BMI088 is strapped for SPI while wired for I2C, the GPS UART TX/RX lines are not crossed, and the 5 V buck feedback resistor R5 is 8k8 instead of 6k8, producing an incorrect output voltage."
}

